// Small sample formatter for the video (not Prettier):
// turns double quotes into single quotes and adds a header line.
const fs = require("fs");
let d = "";
process.stdin.on("data", c => d += c).on("end", () => {
  const p = (JSON.parse(d).tool_input || {}).file_path || "";
  if (!p.endsWith(".js")) process.exit(0);
  let s = fs.readFileSync(p, "utf8").replace(/"/g, "'");
  if (!s.startsWith("// formatted")) s = "// formatted with format.js\n" + s;
  fs.writeFileSync(p, s);
});
